import{_ as i,l as o,o as e,c as l,v as t,p as s,x as n,d as p,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"供应链网络因子","description":"","frontmatter":{"title":"供应链网络因子","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/supply-chain-graph-factor.md","filePath":"quant/supply-chain-graph-factor.md","lastUpdated":1789023840000}'),c={name:"quant/supply-chain-graph-factor.md"};function d(A,a,u,B,m,_){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="供应链网络因子" tabindex="-1">供应链网络因子 <a class="header-anchor" href="#供应链网络因子" aria-label="Permalink to &quot;供应链网络因子&quot;">​</a></h1><div class="epigraph"><p>客户收益能够预测供应商随后的收益；把已披露的贸易边写成可交易的截面信号时，滞后、行业中性与发表后衰减决定它还是不是同一件事。</p><footer>—— Cohen and Frazzini, Economic Links and Predictable Returns, Journal of Finance, 2008</footer></div><p><a href="/quant/supply-chain-alt">供应链与货运</a> 把边、中断与运价放在一张地图上。本篇收窄到<strong>可复制的截面因子</strong>：如何从客户–供应商图构造信号、它与行业动量和会计动量的关系、以及网络拓扑本身（集中度、中心性）何时应被当成风险而不是 alpha。Cohen 与 Frazzini（2008）是锚。Menzly 与 Ozbas（2010）用投入产出表把边从公司对扩到行业对。Herskovic（2018）把生产网络的集中度变化写成资产定价因子。Barrot 与 Sauvagnat、Carvalho 等人用灾害识别边的强度，那是事件研究，容量有限，只为校准边权服务。图上的可学习版本见 <a href="/quant/gnn-asset-pricing">GNN 资产定价</a>；本篇先把手工因子写清楚，以免神经网络重新发明一列未滞后的客户收益。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>横截面习惯用行业哑变量吸收「同一生意」。汽车零部件与整车厂可能不在同一 GICS 叶子，但需求冲击共用。Cohen–Frazzini 的观察是：客户的公开收益与盈余已经可交易，供应商价格却滞后调整，于是沿边有可预测性。问题是测量。美国 10-K 的客户披露有销售占比门槛，图稀疏、滞后且偏向大客户；中国上市公司大客户附注同样截断。用一张静态邻接去预测十年，等于假设拓扑不变。</p><p>第二句话是因子的左边。客户动量组合的收益，是供应商随后收益的预测变量，还是所有公司都要加载的系统性网络风险？前者是 alpha 候选（有限注意），后者是 Herskovic 式的风险价格。把客户动量的多空夏普写成「网络风险溢价」，或把集中度因子写成「供应链 alpha」，都是把论文的回归左边换掉。</p><h3 id="边必须属于信息集" tabindex="-1">边必须属于信息集 <a class="header-anchor" href="#边必须属于信息集" aria-label="Permalink to &quot;边必须属于信息集&quot;">​</a></h3><p>年报披露有法定日期。用财政年度 \\(t\\) 的客户名单去解释日历年 \\(t\\) 的收益，是前视。正确做法是：边在披露可获得之后才进入 \\(A_t\\)，并对公告日后的供应商收益做预测。修订与回溯（数据商后来补全的客户链）必须按 vintage 处理，与<a href="/quant/point-in-time">时点基本面</a>同一纪律。IO 表是年份粗、覆盖宽的边，适合行业级因子；公司级客户名单适合个股因子。两者不要在同一回归里假装是同一张图。</p><p><span class="marginnote">客户动量一旦进入 ETF、风险模型与卖方模板，Cohen–Frazzini 的滞后会缩短。复制应报告发表后子样本，而不是只重复 1980–2004 的表。这与 McLean–Pontiff 对异常衰减的逻辑相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>客户动量（公司级）。</strong> 在 \\(t\\)，对每个供应商 \\(i\\)，取其已披露客户集合 \\(\\mathcal{C}_{i,t}\\)，用销售占比 \\(w_{ij}\\) 加权客户在最近一个月（或一周）的收益，得到</p> \\[x_{i,t}=\\sum_{j\\in\\mathcal{C}_{i,t}} w_{ij}\\,r_{j,t}. \\]<p>\\(x_{i,t}\\) 在截面 rank 后，控制行业、规模与供应商自身滞后收益，看 \\(i\\) 随后的收益。稳健性：去掉同行业边、只用新公告的客户、把边权改成等权。这是 Cohen–Frazzini 的可交易翻译。</p><p><strong>IO 动量（行业级）。</strong> 按 Menzly–Ozbas：用投入产出表定义上游 / 下游行业组合，用相关行业的滞后收益预测本行业。它更宽、更慢，适合作为风险模型里的附加因子，而不是日频选股。</p><p><strong>拓扑风险。</strong> 按 Herskovic：从生产网络估计集中度或中心性的时间序列，看其冲击是否被定价。这边的左边是资产对网络状态的载荷，不是 \\(x_{i,t}\\) 的多空。中心节点的特异性应进入<a href="/quant/stat-risk-pca">统计风险 PCA</a> 的残差协方差，否则风险预算会低估聚集。</p><p>事件研究（灾害、封港）用来估计边的传递系数，供 \\(w_{ij}\\) 校准，不要把事件窗的异常收益年化成因子夏普。</p><h3 id="中性化与双重计算" tabindex="-1">中性化与双重计算 <a class="header-anchor" href="#中性化与双重计算" aria-label="Permalink to &quot;中性化与双重计算&quot;">​</a></h3><p>客户往往与供应商同周期，行业动量会混进 \\(x_{i,t}\\)。必须报告去掉同行业边之后的 IC。客户盈余公告与<a href="/quant/pead-sue">PEAD</a> 重叠：同一则客户盈利意外既出现在新闻里，也出现在图上，见<a href="/quant/news-nlp-alpha">舆情</a>。增量 \\(R^2\\) 应在控制 PEAD、行业动量与供应商自身动量之后再报。否则「供应链因子」只是把已有因子沿边平均了一次。</p>',18)),(e(),s(h,null,{default:n(()=>[E(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIS%5B%22%E5%B7%B2%E6%8A%AB%E9%9C%B2%E5%AE%A2%E6%88%B7%20%2F%20IO%20%E8%A1%A8%22%5D%20--%3E%20PIT%5B%22%E6%BB%9E%E5%90%8E%E5%88%B0%E5%8F%AF%E8%8E%B7%E5%BE%97%E6%97%A5%22%5D%0A%20%20PIT%20--%3E%20XM%5B%22%E5%AE%A2%E6%88%B7%E5%8A%A0%E6%9D%83%E6%94%B6%E7%9B%8A%20x%22%5D%0A%20%20XM%20--%3E%20NEU%5B%22%E8%A1%8C%E4%B8%9A%E4%B8%8E%E8%A7%84%E6%A8%A1%E4%B8%AD%E6%80%A7%22%5D%0A%20%20NEU%20--%3E%20IC%5B%22%E9%9A%8F%E5%90%8E%E4%BE%9B%E5%BA%94%E5%95%86%E6%94%B6%E7%9B%8A%22%5D%0A%20%20TOPO%5B%22%E7%BD%91%E7%BB%9C%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%20--%3E%20RISK%5B%22%E6%8B%93%E6%89%91%E9%A3%8E%E9%99%A9%E5%9B%A0%E5%AD%90%22%5D%0A%20%20IC%20--%3E%20ALPHA%5B%22%E6%9C%89%E9%99%90%E6%B3%A8%E6%84%8F%E5%80%99%E9%80%89%22%5D%0A%20%20RISK%20--%3E%20COV%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%E4%B8%8E%E6%BA%A2%E4%BB%B7%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有限注意：覆盖沿 SIC / GICS，不沿客户名单，信息从客户价格传到供应商需要时间。共同分析师、共同机构持股增加时，滞后应下降——这是机制检验。风险：不对称的投入产出使特质冲击变成宏观波动（Acemoglu 等）；持有中心节点等于持有不可分散的网络风险，要求溢价。中断：边暂时断开时，邻域的符号在供应商、客户与竞争对手之间不同（Barrot–Sauvagnat），全样本线性因子无法表达这种状态依赖；那是压力情景，不是每日 \\(x_{i,t}\\) 的理由。</p><p>与货运指数的分工：运价是宏观与航运供给的混合物，符号对货主与航运相反。网络因子是公司之间的相对收益。把 BDI 动量加进同一棵树，会与贸易周期共线，见供应链与货运篇。预先指定主路径：公司边或 IO 边；运价只做增量。</p><p><span class="marginnote">销售占比作边权会偏向大客户。大客户本身流动性好、调整快，信号可能更弱；小客户边更有信息、更不可交易。因子研究应同时报加权与等权、以及按供应商流动性分层的净 IR。</span></p><h3 id="从手工因子到图模型" tabindex="-1">从手工因子到图模型 <a class="header-anchor" href="#从手工因子到图模型" aria-label="Permalink to &quot;从手工因子到图模型&quot;">​</a></h3><p>\\(x_{i,t}\\) 是一阶邻居的线性聚合。GNN 把它换成可训练的核。若 GNN 不能在同一 vintage 图上打败 \\(x_{i,t}\\)，深度没有经济增量。若打败了，仍要做发表后衰减与可交易约束。手工因子是必须先赢的基准，地位与 GKX 里的弹性网相同。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用未授权的发票或海关微观记录去加密图后声称可复制。不要做日频「供应链 alpha」却用年度边——那是把年报事件涂成每日 IC。A 股壳与退市使边的生存偏差更大，成分过滤应在回测内完成。指数化之后，客户动量的容量在小供应商上差，见<a href="/quant/capacity-participation">容量</a>。</p><p><span class="marginnote">「供应链金融」在银行里指应付账款与保理，与本篇的股票截面因子不是同一对象。风险报告里应分栏，不要把贸易信用风险与客户动量暴露加在一个数里。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Cohen–Frazzini 的客户动量是供应链网络因子的可交易内核；边必须滞后到可获得，并报告发表后衰减。</li><li>Menzly–Ozbas 的 IO 边更宽，适合行业层；Herskovic 的集中度是风险，不是同一列 alpha。</li><li>须对行业动量、PEAD 与自身动量做增量，避免沿边重复计算。</li><li>手工一阶聚合是 GNN 的基准；事件研究只校准边权，不年化夏普。</li><li>出处：Cohen and Frazzini, <em>JF</em>, 2008；Menzly and Ozbas, <em>JF</em>, 2010；Herskovic, <em>JF</em>, 2018；Acemoglu et al., <em>Econometrica</em>, 2012；Barrot and Sauvagnat, <em>QJE</em>, 2016。</li></ul>',11))])}const q=i(c,[["render",d]]);export{C as __pageData,q as default};
